CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL,password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires REAL NOT NULL,last_seen REAL NOT NULL);
CREATE TABLE IF NOT EXISTS auth_attempts(subject TEXT NOT NULL,created REAL NOT NULL);
CREATE INDEX IF NOT EXISTS ix_auth_attempts ON auth_attempts(subject,created);
CREATE TABLE IF NOT EXISTS employees(id TEXT PRIMARY KEY,user_id TEXT,created_by TEXT NOT NULL,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT NOT NULL,client TEXT NOT NULL,track TEXT NOT NULL,status TEXT NOT NULL,fields TEXT NOT NULL DEFAULT '{}',verification TEXT NOT NULL DEFAULT '{}',version INTEGER DEFAULT 1,deleted_at REAL);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,employee_id TEXT NOT NULL,kind TEXT,classification TEXT,extraction TEXT);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,employee_id TEXT,actor TEXT,action TEXT,details TEXT,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS chat_conversations(id TEXT NOT NULL,user_id TEXT NOT NULL,state TEXT NOT NULL DEFAULT '{}',version INTEGER NOT NULL DEFAULT 1,updated REAL NOT NULL,PRIMARY KEY(user_id,id));
CREATE TABLE IF NOT EXISTS chat_messages(id INTEGER PRIMARY KEY,conversation_id TEXT NOT NULL,user_id TEXT NOT NULL,role TEXT NOT NULL,content TEXT NOT NULL,created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS pending_actions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,conversation_id TEXT NOT NULL,operation TEXT NOT NULL,payload TEXT NOT NULL,expires REAL NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS imports(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,preview TEXT NOT NULL,expires REAL NOT NULL,confirmed INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS document_previews(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,conversation_id TEXT NOT NULL,result TEXT NOT NULL,expires REAL NOT NULL,used INTEGER NOT NULL DEFAULT 0);
